RTL_SPLAY_LINKS * WINAPI RtlSubtreePredecessor(RTL_SPLAY_LINKS *links)
{
    RTL_SPLAY_LINKS *child;

    TRACE("(%p)\n", links);

    child = RtlLeftChild(links);
    if (!child)
        return NULL;

    while (RtlRightChild(child))
        child = RtlRightChild(child);

    return child;
}
